fn inl_GetInitVal_unfused<'a>(ctx: &'a Ctx) -> u32 {
    let mut tmp: u32 = 0;
    let mut tick: u32 = 0;
    tick = fns::OSGetTick(ctx);
    fns::srand(ctx, tick);
    tmp = (0x7fec8000_i32 as u32);
    tmp = (tmp | (fns::rand(ctx) as u32));
    tmp = (tmp & 0xfffff000_u32);
    return tmp;
}

